css:
.glowing-box {
  isolation: isolate;
  overflow: hidden;
  border-radius: 999px;
  display: inline-block;
  position: relative;
  transition: 0.4s cubic-bezier(0.77, -0.68, 0.62, 1.23);
}

.glowing-box:hover {
  transition: 0.4s cubic-bezier(0.77, -0.68, 0.62, 1.23);
  transform: scale(1.2);
  box-shadow: 1px 1px 20px 1px rgba(194, 156, 255, 0.05);
}

.glowing-box-active .glowing-box-animations,
.glowing-box-active .glowing-box-borders-masker {
  opacity: 1;
}
.glowing-box-animations {
  opacity: 0;
  pointer-events: none;
  transition: 1s ease opacity;
}
.glowing-box-animations,
.glowing-box-borders {
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
}

.glowing-box-animations:before,
.glowing-box-borders:before {
  content: "";
  float: left;
  padding-top: 100%;
}
.glowing-box-animations {
  opacity: 0;
  pointer-events: none;
  transition: 1s ease opacity;
}

.glowing-box-glow {
  filter: blur(10px);
  opacity: 0.1;
}

.glowing-box-animations * {
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

.glowing-box-stars-masker {
  /* I used BASE 64 to add the background pattern to the URL mask, but you can download the background here: i.imgur.com/oOtlWvp.png */
  -webkit-mask: url(data:image/svg+xml;base64,);
  mask: url(data:image/svg+xml;base64,);
  -webkit-mask-repeat: repeat;
  mask-repeat: repeat;
  -webkit-mask-size: 13%;
  mask-size: 13%;
}

.glowing-box-animations * {
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

.glowing-box-borders,
.glowing-box-glow,
.glowing-box-stars {
  animation: borderTurn var(--animation-speed) infinite linear;
  background-image: conic-gradient(
    from 0 at 50% 50%,
    rgba(255, 255, 255, 0.5) 0deg,
    rgba(255, 255, 255, 0) 60deg,
    rgba(255, 255, 255, 0) 310deg,
    rgba(255, 255, 255, 0.5) 360deg
  );
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
}

.glowing-box-animations * {
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

.glowing-box-animations:after,
.glowing-box-borders:after {
  clear: both;
  content: "";
  display: block;
}

.glowing-box-active .glowing-box-animations,
.glowing-box-active .glowing-box-borders-masker {
  opacity: 1;
}
.glowing-box-borders-masker {
  border-radius: 999px;
  content: "";

  inset: 0;
  left: 0;
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask-composite: xor;
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  padding: 0.5px;
  pointer-events: none;
  position: absolute;
  top: 0;
  transition: 1s ease opacity;
}

.glowing-box-borders {
  animation-name: borderTurnWithTranslate;
}

.glowing-box-animations,
.glowing-box-borders {
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 100%;
}

.glowing-box-animations:before,
.glowing-box-borders:before {
  content: "";
  float: left;
  padding-top: 100%;
}

.glowing-box-animations:after,
.glowing-box-borders:after {
  clear: both;
  content: "";
  display: block;
}

.glowing-box-button {
  background: radial-gradient(
      107.5% 107.5% at 50% 215%,
      rgba(255, 255, 255, 0.24) 0%,
      rgba(255, 255, 255, 0) 100%
    ),
    rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  cursor: pointer;
  padding: 7px 24px;
  position: relative;
  z-index: 1;
}
.glowing-box-button {
  font-feature-settings:
    "cv06" on,
    "calt" off,
    "liga" off;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 24px;
}

.glowing-box .glowing-box-button {
  overflow: visible;
}
glowing-box-button {
  background-color: transparent;
  border: 1px solid transparent;
  font-family: inherit;
  font-size: 100%;
  line-height: 1.15;
  margin: 0;
}
.glowing-box .glowing-box .glowing-box-button {
  -webkit-appearance: button;
  -moz-appearance: button;
  appearance: button;
  cursor: pointer;
}

.glowing-box-button:after {
  background: radial-gradient(
    73% 117% at 50% 126%,
    rgb(38 3 95 / 82%) 0%,
    rgb(255 255 255 / 0%) 100%
  );
  border-radius: 999px;
  content: "";
  height: calc(100% + 4px);
  left: -2px;
  opacity: 0;
  position: absolute;
  top: -2px;
  transition: 1s all;
  width: calc(100% + 4px);
}

.glowing-box-button .glowing-span {
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.3) 8.85%,
    #ffffff 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  display: block;
}

.glowing-box-button:hover:after {
  opacity: 0.7;
}

@keyframes borderTurnWithTranslate {
  0% {
    transform: translate(-50%, -50%) rotate(0);
  }
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}

@keyframes borderTurn {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
